package run.ikaros.reading; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/reading/preferences") public class ReadingPreferenceController{private final ReadingPreferenceService service;public ReadingPreferenceController(ReadingPreferenceService s){service=s;}@PutMapping public Mono<ReadingPreferenceView> update(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@RequestParam ReadingPreferenceScope scope,@RequestParam(required=false)String kind,@RequestParam(required=false)UUID workId,@Valid@RequestBody UpdateReadingPreferenceRequest r){return service.update(o,scope,kind,workId,r);}@GetMapping public Mono<ReadingPreferenceView> get(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@RequestParam ReadingPreferenceScope scope,@RequestParam(required=false)String kind,@RequestParam(required=false)UUID workId){return service.get(o,scope,kind,workId);}}
